import { apiPlaygroundDisplayTypes, iconTypes } from '@mintlify/models';
import { z } from 'zod';
const pageMetaTagsSchema = z
    .object({
    href: z.string(),
    title: z.string(),
    'og:title': z.string(),
    sidebarTitle: z.string(),
    description: z.string(),
    api: z.string(),
    openapi: z.string(),
    asyncapi: z.string(),
    contentType: z.string(),
    authMethod: z.string(),
    auth: z.string(),
    version: z.string(),
    mode: z.string(),
    lastUpdatedDate: z.string(),
    createdDate: z.string(),
    'openapi-schema': z.string(),
    icon: z.string(),
    tag: z.string(),
    url: z.string(),
    hideFooterPagination: z.boolean(),
    hideApiMarker: z.boolean(),
    noindex: z.boolean(),
    isPublic: z.boolean(),
    public: z.boolean(),
    authors: z.unknown(),
    iconType: z.enum(iconTypes),
    playground: z.enum(apiPlaygroundDisplayTypes),
    keywords: z.array(z.string()),
})
    .partial();
const xMcpSchema = z
    .object({
    enabled: z.boolean(),
    name: z.string(),
    description: z.string(),
})
    .partial();
const xMintPlaygroundSchema = z
    .object({
    expand: z.boolean(),
})
    .partial();
const xMintSchema = z
    .object({
    metadata: pageMetaTagsSchema,
    content: z.string(),
    href: z.string(),
    mcp: xMcpSchema,
    groups: z.array(z.string()),
    pre: z.array(z.string()),
    post: z.array(z.string()),
    playground: xMintPlaygroundSchema,
})
    .partial();
export function parseXMcp(value) {
    const result = xMcpSchema.safeParse(value);
    return result.success ? result.data : undefined;
}
export function parseXMint(value) {
    const result = xMintSchema.safeParse(value);
    return result.success ? result.data : undefined;
}
